def recv_for_iv(r):
    while True:
        l = r.recvline().decode()
        if 'Enjoy this random bits :' in l:
            bits = l.split(':')[-1].strip()
            return bits

def smart_invert(target_output, aux, k3, k4):
    # input x such that foo(x, aux, k3, k4) == target_output. As all values are 73 bytes, try 0/ff per byte.
    res = bytearray()
    for ti, ai, k3i, k4i in zip(target_output, aux, k3, k4):
        found = False
        for g in (0x00,0xff):
            v = (g&ai&k3i&k4i | g&(ai^255)&(k3i^255)&k4i | g&(ai^255)&k3i&(k4i^255) |
                g&ai&(k3i^255)&(k4i^255) | (g^255)&ai&(k3i^255)&k4i | (g^255)&ai&k3i&(k4i^255))
            if v == ti:
                res.append(g)
                found = True
                break
        if not found:
            raise Exception(f"No input for output={ti}, aux={ai}, k3={k3i}, k4={k4i}")
    return bytes(res)

def main():
    r = remote('rev.chal.csaw.io', 5000)
    r.recvuntil(b'Welcome')
